edits.replacement:
.ui-key.pill{ border-radius:12px; padding:0 9px; }
/* vNN.xx, UI REDESIGN ui5q1a (his #50, from the AAA judge of the title shots 01, 44 and 57): THE MODE LIST READS FROM THE COUCH.
   The mode rows were 13px caps in 40px rows, smaller than the old start button; they are 52px rows with 18px labels now, and
   1 PLAYER is the amber primary at 62px and 22px. The two SERVER rows are shorter and carry their COMING LATER tag inside the row
   at its right end, not hanging off the side of the column. A darker band behind the centre of the title keeps the walking
   Undercroft out from behind the key row and the mode list (the sides still show it, v17.83). The SAVES block is a 900px panel and
   not a 1500px web form: the name box, CHANGE NAME and CREATE A NEW SAVE share one row. No word changed and the rows keep their
   order, so the arrows and the pad walk them as before. */
#root #title.on{ background:radial-gradient(ellipse 75% 85% at 50% 50%, transparent 55%, rgba(6,7,8,.6) 100%),
  linear-gradient(90deg, rgba(17,19,21,.66) 0%, rgba(17,19,21,.9) 26%, rgba(17,19,21,.9) 74%, rgba(17,19,21,.66) 100%); }
#root #modemenu{ gap:6px; margin-top:14px !important; }
#root #title .kbrow, #root #title .padrow{ margin-top:14px !important; }
#root #modemenu button.moderow{ min-width:560px; min-height:52px; padding:0 32px; font-size:18px; font-weight:700; letter-spacing:.1em; }
#root #modemenu #titlestart{ min-height:62px; padding:0 48px !important; font-size:22px !important; letter-spacing:.12em !important; }
#root #modemenu .modelater button.moderow{ min-height:40px; font-size:15px; }
#root #modemenu .modelater span{ left:auto; right:14px; margin-left:0; padding:4px 8px; border:1px solid var(--ui-line); border-radius:2px;
  font-family:var(--f-cond); font-weight:600; font-size:13px; letter-spacing:.12em; color:var(--tx-2); pointer-events:none; }
#root #slotpanel{ max-width:900px; margin-left:auto; margin-right:auto; }

check:
{v:'VER',what:'his #50 (UI redesign ui5q1a, from the AAA judge of the title shots): the mode list reads from the couch: mode rows at least 50px tall with labels of 17px or more, 1 PLAYER larger and taller still, the COMING LATER tag inside its greyed row, and the saves block at most 960px wide with CREATE A NEW SAVE on the name row',
 run:function(){
   var ti=document.getElementById('title'), m=document.getElementById('modemenu'), bad=[], was, b, s, st, sp, tg, br, tr, ng, pn, mw;
   if(!ti||!m) return 'SKIP: no mode menu here';
   was=ti.classList.contains('on');
   try{
     ti.classList.add('on');
     b=document.getElementById('modecoop'); st=document.getElementById('titlestart');
     if(!b) return 'SKIP: no 2 PLAYER CO-OP row here';
     s=getComputedStyle(b);
     if(!(parseFloat(s.fontSize)>=17)) bad.push('a mode row label is '+s.fontSize);
     if(!(parseFloat(s.minHeight)>=50)) bad.push('a mode row is only held to '+s.minHeight+' tall');
     if(st){
       if(!(parseFloat(getComputedStyle(st).fontSize)>=20)) bad.push('1 PLAYER is '+getComputedStyle(st).fontSize);
       if(!(st.getBoundingClientRect().height>b.getBoundingClientRect().height+4)) bad.push('1 PLAYER is no taller than the other rows');
     }
     tg=document.querySelector('#modemenu .modelater span'); b=tg&&tg.parentNode.querySelector('button');
     if(tg&&b){ br=b.getBoundingClientRect(); tr=tg.getBoundingClientRect(); if(br.width>0&&(tr.left<br.left-1||tr.right>br.right+1)) bad.push('the COMING LATER tag hangs outside its row'); }
     sp=document.getElementById('slotpanel');
     if(sp){ mw=parseFloat(getComputedStyle(sp).maxWidth); if(!(mw<=960)) bad.push('the saves block has no width cap ('+getComputedStyle(sp).maxWidth+')'); }
     ng=document.getElementById('newgame'); pn=document.getElementById('pnamein');
     if(ng&&pn&&ng.parentNode!==pn.parentNode) bad.push('CREATE A NEW SAVE is a full width row of its own under the name box');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ if(!was) ti.classList.remove('on'); try{ if(typeof titleFit==='function') titleFit(); }catch(_t){} }
   return bad.length?bad.join('; '):null; }},
